To compare two Excel files and show discrepancies in Node.js, you can use a library like `xlsx` to read the Excel files and `lodash` for comparison. Here's a basic example:

First, install the necessary dependencies:

```bash
npm install xlsx lodash
```

Then, create a script to compare the files:

```javascript
const XLSX = require('xlsx');
const _ = require('lodash');

function compareExcelFiles(file1, file2, sheetName) {
  const workbook1 = XLSX.readFile(file1);
  const workbook2 = XLSX.readFile(file2);

  const sheet1 = workbook1.Sheets[sheetName];
  const sheet2 = workbook2.Sheets[sheetName];

  const keys1 = _.keys(sheet1);
  const keys2 = _.keys(sheet2);

  const differences = [];

  keys1.forEach((key1) => {
    if (!_.includes(keys2, key1)) {
      differences.push({ file: file1, key: key1 });
    }
  });

  keys2.forEach((key2) => {
    if (!_.includes(keys1, key2)) {
      differences.push({ file: file2, key: key2 });
    }
  });

  Object.keys(sheet1).forEach((key) => {
    const value1 = sheet1[key].v;
    const value2 = sheet2[key].v;

    if (value1 !== value2) {
      differences.push({
        file: file1,
        key,
        value1,
        value2,
      });
    }
  });

  return differences;
}

// Usage
const differences = compareExcelFiles('file1.xlsx', 'file2.xlsx', 'Sheet1');
console.log(differences);
```

This script reads two Excel files, compares the specified sheet, and returns an array of objects containing the differences. Each object has properties `file`, `key`, `value1`, and `value2`. The `file` property indicates the file where the difference was found, the `key` property is the column header, and `value1` and `value2` are the values in the corresponding cells in the two files.

