import java.util.Scanner;

public class Game {
    private Scanner scanner = new Scanner(System.in);

    public void showDialogue(Dialogue dialogue) {
        System.out.println(dialogue.getText());
        int choiceIndex = 1;
        for (String choice : dialogue.getChoices()) {
            System.out.println(choiceIndex + ". " + choice);
            choiceIndex++;
        }

        System.out.print("Enter your choice (number): ");
        int choice = scanner.nextInt();
        if (choice > 0 && choice <= dialogue.getChoices().size()) {
            // Handle the chosen choice here
            String chosenChoice = dialogue.getChoices().get(choice - 1);
            handleChoice(chosenChoice);
        } else {
            System.out.println("Invalid choice. Please try again.");
            showDialogue(dialogue); // Recursively call the method to show the dialogue again
        }
    }

    public void handleChoice(String chosenChoice) {
        // Handle the chosen choice here
        System.out.println("You chose: " + chosenChoice);
    }
}
```

